export interface LivingFields extends EntityFields, FallDamageLogicDataFields {
  health?: number;
  /** How much absorption health it has. */
  absorptionAmount?: number;
  /** Timer since it has been damaged. Counts down to zero. */
  hurtTime?: number;
  /** Ticks since it was last damaged, from its creation. */
  hurtByTimestamp?: number;
  /** Timer since it was marked as dead. Counts down to zero. */
  deathTime?: number;
  /** Whether it will glide when it falls. */
  fallFlying?: boolean;
  /** X coordinate of where it is sleeping. */
  sleepingX?: number;
  /** Y coordinate of where it is sleeping. */
  sleepingY?: number;
  /** Z coordinate of where it is sleeping. */
  sleepingZ?: number;
  sleepingPos?: readonly number[];
  brain?: NbtInput;
  attributes?: readonly NbtInput[];
  /** Active potion effects */
  activeEffects?: readonly NbtInput[];
  /** Team to join when it is spawned. */
  team?: string;
  /** The UUID of the player that last hurt this entity. Stored for 100 ticks. */
  lastHurtByPlayer?: readonly number[];
  /** Amount of ticks that this entity will remember the player that last hurt this entity. Counts down from 100 to 0. */
  lastHurtByPlayerMemoryTime?: number;
  /** The UUID of the mob that last hurt this entity. Stored for 100 ticks. */
  lastHurtByMob?: readonly number[];
  /** Amount of ticks since this entity was last hurt by a mob. Counts up from 0 to 100. */
  ticksSinceLastHurtByMob?: number;
  locatorBarIcon?: WaypointIconFields;
}

