/** `minecraft:blaze`, `minecraft:breeze`, `minecraft:cave_spider`, `minecraft:elder_guardian`, `minecraft:giant`, `minecraft:guardian`, `minecraft:silverfish`, `minecraft:spider`, `minecraft:stray`, `minecraft:wither_skeleton`, `minecraft:parched` */
export interface MobFields extends LivingFields {
  /** [main hand, offhand] */
  handItems?: readonly NbtInput[];
  /** Chance to drop the items it is holding, in [main hand, offhand].  `0.0` is hardcoded to be unaffected by enchantments. \ Values between `0.0` and `1.0` (inclusive) randomizes durability of the dropped item. */
  handDropChances?: readonly number[];
  /** [feet, legs, body, head] */
  armorItems?: readonly NbtInput[];
  /** Chance to drop the items it is wearing, in [feet, legs, body, head].  `0.0` is hardcoded to be unaffected by enchantments. \ Values between `0.0` and `1.0` (inclusive) randomizes durability of the dropped item. */
  armorDropChances?: readonly number[];
  /** Used for wolf armor & llama carpet decoration. */
  bodyArmorItem?: NbtInput;
  /** Chance to drop the item it is wearing. */
  bodyArmorDropChance?: number;
  /** The equipment items of the mob, such as armor or weapons. */
  equipment?: EquipmentInput;
  /** Chances of the mob dropping an equipment slot on death. */
  dropChances?: NbtInput;
  /** Loot table that is dropped when the mob dies. */
  deathLootTable?: string;
  /** Seed for generating the death loot table. */
  deathLootTableSeed?: number;
  /** Whether it can pick up loot. */
  canPickUpLoot?: boolean;
  /** Whether it should not despawn naturally. */
  persistenceRequired?: boolean;
  /** Whether it is left handed. */
  leftHanded?: boolean;
  /** Whether it should have an AI. */
  noAI?: boolean;
  /** What the leash is attached to. */
  leash?: NbtInput;
  /** Defaults to -1, which represents "no home". */
  homeRadius?: number;
  /** This field will be discarded if `home_radius` is less than 0. */
  homePos?: readonly number[];
}

export const MOB: EntityNbtSchema<MobFields> = {
  ...LIVING,
  handItems: field({ key: "HandItems", encode: asList, until: "1.21.5" }),
  handDropChances: field({ key: "HandDropChances", encode: asFloats, until: "1.21.5" }),
  armorItems: field({ key: "ArmorItems", encode: asList, until: "1.21.5" }),
  armorDropChances: field({ key: "ArmorDropChances", encode: asFloats, until: "1.21.5" }),
  bodyArmorItem: field({ key: "body_armor_item", since: "1.20.5", until: "1.21.5" }),
  bodyArmorDropChance: field({ key: "body_armor_drop_chance", encode: Float, since: "1.20.5", until: "1.21.5" }),
  equipment: field({ key: "equipment", encode: asEquipment, since: "1.21.5" }),
  dropChances: field({ key: "drop_chances", since: "1.21.5" }),
  deathLootTable: field({ key: "DeathLootTable" }),
  deathLootTableSeed: field({ key: "DeathLootTableSeed", encode: Long }),
  canPickUpLoot: field({ key: "CanPickUpLoot", encode: asByte }),
  persistenceRequired: field({ key: "PersistenceRequired", encode: asByte }),
  leftHanded: field({ key: "LeftHanded", encode: asByte }),
  noAI: field({ key: "NoAI", encode: asByte }),
  leash: (v, version): Record<string, NbtInput> =>
    atLeast(version, "1.20.5")
      ? { leash: v }
      : { Leash: v },
  homeRadius: field({ key: "home_radius", since: "1.21.6" }),
  homePos: field({ key: "home_pos", encode: IntArray, since: "1.21.6" }),
};

